import{Ct as e,Q as t,rt as n,t as r,tt as i}from"./chunks/framework.MmGQnsr5.js";var a=JSON.parse(`{"title":"Note","description":"","frontmatter":{"title":"Note","order":1},"headers":[],"relativePath":"services/note/index.md","filePath":"services/note/index.md"}`),o={name:`services/note/index.md`};function s(r,a,o,s,c,l){return e(),i(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...a[0]||=[n(`<h1 id="note-service" tabindex="-1">Note Service <a class="header-anchor" href="#note-service" aria-label="Permalink to “Note Service”">​</a></h1><p>Go service owning workspaces, folders, note metadata, links, tags and trash. DDD + CQRS, with a transactional outbox for integration events. Note only stores note metadata; the editable binary content lives in the <a href="./../document/">Document service</a>.</p><ul><li><a href="./domain.html">Domain</a>: class diagrams</li><li><a href="./data.html">Data</a>: database schema</li><li><a href="./flows.html">Flows</a>: sequence diagrams</li><li><a href="./events.html">Events</a>: topics published and consumed</li></ul><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Operations and behavior</th></tr></thead><tbody><tr><td>Workspaces</td><td>Create, rename, change slug, delete, list and look up workspaces; creation also creates a root folder and owner membership.</td></tr><tr><td>Membership</td><td>List and update members, leave a workspace and search users. Member limits and payer protection apply to membership changes.</td></tr><tr><td>Folders and notes</td><td>Create, rename, change icons and move items; read notes and the workspace tree. Metadata is separate from document content.</td></tr><tr><td>Trash</td><td>Trash, restore, permanently delete or empty trash; a scheduled retention purge removes expired trash.</td></tr><tr><td>Discovery</td><td>Read links and graphs, and request a workspace-scoped search token. Graphs are subject to billing entitlements.</td></tr><tr><td>Document commits</td><td>Consume committed content to update note size, tags and outgoing links.</td></tr></tbody></table><p>See <a href="./flows.html">Flows</a> for authorization, billing, deletion and asynchronous event paths. Note and workspace publishing handlers are currently stubs, not implemented publishing workflows.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2>`,7),t(`figure`,{class:`vpd-diagram vpd-diagram--d2`,onclick:`
        const figure = this;
        const isFullscreen = figure.classList.contains('vpd-diagram--fullscreen');

        document.querySelectorAll('.vpd-diagram').forEach(diagram => {
          diagram.classList.remove('vpd-diagram--fullscreen');
        });

        if (!isFullscreen) {
          figure.classList.add('vpd-diagram--fullscreen');
        }
      `},[t(`img`,{src:`/notopia/pr/294/diagrams/d2-architecture-note-diagram-3b4c62eafe7cabdf266e2022524a11e1.svg`,alt:`d2 Diagram`,class:`vpd-diagram-image`})],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};